let lang='th',view='home',lab=0,variant=0,sound=false,audioContext=null,screen=0;
const t=k=>words[lang][k]||k;
function beep(){if(!sound)return;try{audioContext=audioContext||new(window.AudioContext||window.webkitAudioContext)();const o=audioContext.createOscillator(),g=audioContext.createGain();o.connect(g);g.connect(audioContext.destination);o.frequency.value=620;g.gain.setValueAtTime(.08,audioContext.currentTime);g.gain.exponentialRampToValueAtTime(.001,audioContext.currentTime+.16);o.start();o.stop(audioContext.currentTime+.17)}catch{}}
function translate(){document.documentElement.lang=lang;document.title=lang==='en'?'Choose clearly! • UX/UI Mini-game Lab | Code Genius':'กดให้ถูก! • UX/UI Mini-game Lab | Code Genius';$$('[data-t]').forEach(el=>el.textContent=t(el.dataset.t));$('#lang').textContent=lang==='th'?'EN':'ไทย';$('#sound span').textContent=t(sound?'soundOn':'soundOff');renderLab();renderPreset();renderCases();renderMissions();renderStory();renderInquiry();renderJourneyQuiz();renderFun();renderRoute();if(deckReady)updateDeckLabels();}
function navigateSection(v){view=v;$$('.view').forEach(s=>s.hidden=s.id!==v);$$('[data-view]').forEach(b=>{b.classList.toggle('active',b.dataset.view===v);b.setAttribute('aria-current',b.dataset.view===v?'page':'false')});window.scrollTo({top:0,behavior:'auto'});}
$$('[data-view]').forEach(b=>b.onclick=()=>navigate(b.dataset.view));$$('[data-go]').forEach(b=>b.onclick=()=>navigate(b.dataset.go));$('.brand').onclick=e=>{e.preventDefault();navigate('home')};
$('#lang').onclick=()=>{lang=lang==='th'?'en':'th';translate()};$('#sound').onclick=()=>{sound=!sound;$('#sound').setAttribute('aria-pressed',sound);$('#sound span').textContent=t(sound?'soundOn':'soundOff');beep()};$('#fullscreen').onclick=async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else await document.documentElement.requestFullscreen()}catch{}};
const labText={th:[['กดดาวหนึ่งครั้ง','ปุ่มแบบไหนกดง่ายกว่า เพราะอะไร?','ตำแหน่ง สี และหน้าที่เหมือนเดิม เปลี่ยนเฉพาะขนาดปุ่ม','ปุ่มที่กดได้ง่ายช่วยลดการกดพลาด แต่ขนาดที่เหมาะต้องดูหน้าจอและผู้ใช้ด้วย'],['เลือกปุ่ม “ขอคำใบ้”','ถ้าไม่มีคำ เรารู้หน้าที่ของปุ่มแน่ไหม?','รูปและตำแหน่งเหมือนเดิม แบบ B เพิ่มคำกำกับเท่านั้น','สัญลักษณ์ช่วยให้จำได้ แต่คนอาจตีความต่างกัน คำกำกับช่วยบอกหน้าที่ให้ชัด'],['กดส่งคำตอบหนึ่งครั้ง แล้วรอดู','รู้ได้อย่างไรว่าระบบรับคำตอบแล้ว?','แบบ A และ B รับคำตอบเหมือนกัน ต่างกันที่สิ่งที่ผู้ใช้เห็นหลังการกด','ผลตอบกลับบอกว่าระบบรับคำตอบแล้ว ลดความไม่แน่ใจและการกดซ้ำ ไม่จำเป็นต้องมีเสียงเสมอไป']],en:[['Tap the star once','Which button is easier to tap? Why?','Same position, colour and action. Only the button size changes.','An easier-to-tap button can reduce missed taps. The right size still depends on the screen and the user.'],['Choose “Get a hint”','Without words, can we be sure what a button does?','Same icons and positions. B adds labels only.','Icons can be memorable, but people may interpret them differently. Labels help explain the action.'],['Submit once, then watch','How do you know the answer was received?','A and B both receive the answer. Only the visible response changes.','Feedback shows that the system received the answer. It reduces uncertainty and repeated presses. Sound is not always needed.']]};
const labStates=Array.from({length:3},()=>[{done:false,shown:false},{done:false,shown:false}]);
function labelOutcome(i){return lang==='en'?['You selected Home. The task asks for a hint. Try another button.','Hint found! Which word or symbol helped you choose?','You selected Next. The task asks for a hint. Try another button.'][i]:['คุณเลือกหน้าหลัก แต่ภารกิจขอคำใบ้ ลองอีกปุ่มได้','พบคำใบ้แล้ว! คำหรือสัญลักษณ์ไหนช่วยให้เลือกได้?','คุณเลือกถัดไป แต่ภารกิจขอคำใบ้ ลองอีกปุ่มได้'][i]}
function renderLab(){const a=$('#arena');a.replaceChildren();$('#labStatus').textContent='';$('#finding').hidden=!labStates[lab][variant].shown;$('#variantTag').textContent=variant?'B':'A';const text=labText[lang][lab];$('#labTask').textContent=text[0];$('#labQuestion').textContent=text[1];$('#labHint').textContent=text[2];$('#labFinding').textContent=text[3];$$('[data-lab]').forEach(b=>b.classList.toggle('active',+b.dataset.lab===lab));if(lab===0){const b=document.createElement('button');b.className='target'+(variant?' large':'');b.textContent='★';b.setAttribute('aria-label',lang==='th'?'กดดาว':'Tap star');b.onclick=()=>{labStates[lab][variant].done=true;$('#labStatus').textContent=t('hit');beep();b.disabled=true};if(labStates[lab][variant].done){b.disabled=true;$('#labStatus').textContent=t('hit')}a.append(b)}else if(lab===1){['⌂','?','→'].forEach((icon,i)=>{const b=document.createElement('button');b.className='icon-choice';b.textContent=icon;b.setAttribute('aria-label',t(['home','help','next'][i]));if(variant){const s=document.createElement('small');s.textContent=t(['home','help','next'][i]);b.append(s)}b.onclick=()=>{labStates[lab][variant].done=true;labStates[lab][variant].choice=i;$('#labStatus').textContent=labelOutcome(i);beep()};a.append(b)});if(labStates[lab][variant].done)$('#labStatus').textContent=labelOutcome(labStates[lab][variant].choice)}else{const box=document.createElement('div');box.className='parcel';box.textContent='✉';box.setAttribute('aria-hidden','true');const b=document.createElement('button');b.textContent=t('send');b.className='primary';let sent=labStates[lab][variant].done;if(sent&&variant){$('#labStatus').textContent=t('received')}b.onclick=()=>{if(variant){sent=true;labStates[lab][variant].done=true;$('#labStatus').textContent=t('received')}else{sent=true;labStates[lab][variant].done=true;/* Deliberately no visible feedback: teaching comparison. */}};a.append(box,b)}}
$$('[data-lab]').forEach(b=>b.onclick=()=>{lab=+b.dataset.lab;variant=0;renderLab()});$('#switchVariant').onclick=()=>{variant=1-variant;renderLab()};$('#retryLab').onclick=()=>{labStates[lab][variant]={done:false,shown:false};renderLab()};$('#reveal').onclick=()=>{labStates[lab][variant].shown=!labStates[lab][variant].shown;$('#finding').hidden=!labStates[lab][variant].shown};
