function renderCases(){const root=$('#useCases');if(!root)return;root.replaceChildren();const en=lang==='en',c=cases[lang][caseIndex],correct=caseIndex===1?1:0;const make=(tag,text,cls)=>{const e=document.createElement(tag);e.textContent=text;if(cls)e.className=cls;return e};root.append(make('h2',en?'Where do we use this?':'เรื่องนี้ใช้ที่ไหน?'),make('p',en?'Choose a situation. Predict, reveal, then try your own design.':'เลือกสถานการณ์ คิดก่อนเฉลย แล้วนำไปออกแบบของเราเอง'));const tabs=make('div','','case-tabs');cases[lang].forEach((item,i)=>{const b=make('button',item.name,i===caseIndex?'active':'');b.setAttribute('aria-pressed',i===caseIndex);b.onclick=()=>{caseIndex=i;caseAnswer=null;renderCases()};tabs.append(b)});root.append(tabs);const grid=make('div','','case-grid'),visual=make('div','','case-device'),details=make('div','','case-details');const solved=caseAnswer===correct;visual.append(make('div',c.icon,'case-symbol'),make('strong',solved?(en?'After the change':'หลังปรับ'):(en?'Before the change':'ก่อนปรับ')));const controls=make('div','','case-controls');(solved?c.after:c.before).forEach(x=>controls.append(make('span',x,caseIndex===2&&!solved?'tiny':'')));visual.append(controls);details.append(make('p',c.goal),make('h3',c.question));c.answers.forEach((x,i)=>{const b=make('button',x,'case-answer');b.onclick=()=>{caseAnswer=i;renderCases()};details.append(b)});const response=make('p',caseAnswer===null?'':solved?c.why:(en?'That does not solve this problem yet. What does the user need to see or do?':'ยังไม่แก้ปัญหานี้ ผู้ใช้ต้องเห็นหรือทำอะไรได้?'),'case-response');response.setAttribute('role','status');details.append(response);if(solved){const task=make('p',c.task,'case-transfer');const labButton=make('button',en?'Test this idea in the lab →':'ลองหลักการนี้ในห้องทดลอง →','primary');labButton.onclick=()=>{lab=c.link;variant=0;renderLab();navigate('lab')};details.append(task,labButton)}grid.append(visual,details);root.append(grid);root.append(make('small',en?'Illustrated classroom examples, not real ordering systems. Draw your own paper prototype, then watch a friend point to its controls.':'ตัวอย่างจำลองสำหรับเรียน ไม่ใช่ระบบสั่งซื้อจริง วาดต้นแบบของตัวเองบนกระดาษ แล้วสังเกตเพื่อนลองชี้ปุ่ม'))}


let missionIndex=0,missionVariant=0,missionStep=0,missionChoice=-1,missionCount=0,missionHint=false,missionChecked=false;
const missionNotes=[['',''],['','']];
const missionReflections=Array.from({length:2},()=>Array.from({length:2},()=>({criterion:'0',judgement:'unsure',change:''})));

function resetMission(){missionStep=0;missionChoice=-1;missionCount=0;missionHint=false;missionChecked=false;renderMissions()}
function renderMissions(){const root=$('#realMissions');if(!root)return;const en=lang==='en',tr=(th,eng)=>en?eng:th;root.replaceChildren();const el=(tag,text,cls)=>{const e=document.createElement(tag);e.textContent=text;if(cls)e.className=cls;return e};const button=(txt,fn,cls='')=>{const b=el('button',txt,cls);b.onclick=fn;return b};root.append(el('h2',tr('ลองใช้จริง: แบบไหนทำให้ติด?','Try it: where do you get stuck?')),el('p',tr('ลอง A แล้ว B บอกว่าจุดไหนช่วยหรือทำให้สับสน เพราะผู้ใช้ต้องทำอะไร ไม่จับเวลา ถ้าติดใช้คำใบ้ได้','Try A, then B. Identify what helps or confuses the user and why it matters for their task. No timer. Hints are allowed.')));const tabs=el('div','','case-tabs');[tr('น้ำดื่มให้น้อง','Water for a younger child'),tr('สั่งข้าวหนึ่งจาน','Order one rice meal')].forEach((s,i)=>{const b=button(s,()=>{missionIndex=i;missionVariant=0;resetMission()},i===missionIndex?'active':'');b.setAttribute('aria-pressed',i===missionIndex);tabs.append(b)});root.append(tabs);const row=el('div','','mission-tools');row.append(el('strong',tr('แบบ ','Version ')+(missionVariant?'B':'A')),button(tr('สลับ A / B','Switch A / B'),()=>{missionVariant=1-missionVariant;resetMission()}),button(tr('ครูเริ่มทดลองใหม่','Teacher: reset trial'),resetMission),button(tr('ขอคำใบ้','Hint'),()=>{missionHint=!missionHint;renderMissions()}));root.append(row);root.append(el('p',missionIndex===0?tr('ภารกิจ: เลือกน้ำดื่มให้น้อง แล้วยืนยันรายการ','Task: choose drinking water for a younger child, then confirm.'):tr('ภารกิจ: ให้ระบบรับรายการข้าว 1 จาน แล้วตรวจว่าได้ตามเป้าหมายหรือไม่','Task: get one rice meal into the order, then check whether you reached the goal.'),'mission-goal'));const stage=el('div','','mission-stage');const status=el('p','','mission-status');status.setAttribute('role','status');if(missionIndex===0){if(missionStep===0){stage.append(el('div',tr('ตู้เครื่องดื่มจำลอง','Practice drink station'),'mission-title'));[tr('น้ำดื่ม','Water'),tr('น้ำผลไม้','Juice')].forEach((s,i)=>stage.append(button(missionVariant?s:(i?'②':'①'),()=>{missionChoice=i;missionStep=1;renderMissions()})));}else if(missionStep===1){stage.append(el('h3',tr('คุณเลือก: ','You chose: ')+(missionChoice?tr('น้ำผลไม้','Juice'):tr('น้ำดื่ม','Water'))));stage.append(button(missionVariant?tr('เปลี่ยนเครื่องดื่ม','Change drink'):'←',()=>{missionStep=0;renderMissions()}),button(missionVariant?tr('ยืนยันเครื่องดื่ม','Confirm drink'):'→',()=>{if(missionChoice===0){missionStep=2;renderMissions()}else{status.textContent=tr('ภารกิจขอน้ำดื่ม ลองย้อนกลับไปเปลี่ยนได้','The task asks for water. Go back and change your drink.')}}));}else{stage.append(el('h3',tr('สำเร็จ ✓ ได้น้ำดื่มแล้ว','Done ✓ Water selected')));status.textContent=tr('ขั้นตอนไหนที่ต้องเดา? จดไว้แล้วลองอีกแบบ','Which step needed guessing? Note it, then try the other version.');}}else{stage.append(el('div',tr('ร้านข้าวจำลอง','Practice lunch counter'),'mission-title'));const order=button(tr('สั่งข้าว','Order rice'),()=>{missionCount++;if(missionVariant){order.disabled=true;order.textContent=tr('รับรายการแล้ว ✓','Order received ✓');status.textContent=tr('รับข้าว 1 จานแล้ว กดตรวจรายการเพื่อดู','One rice meal received. Check your order to see it.');renderMissions()}});if(missionVariant&&missionCount){order.disabled=true;order.textContent=tr('รับรายการแล้ว ✓','Order received ✓')}stage.append(order,button(tr('ยกเลิกรายการจำลอง','Cancel practice order'),()=>{missionCount=0;missionChecked=true;renderMissions()}),button(tr('ตรวจรายการ','Check order'),()=>{missionChecked=true;renderMissions()}));if(missionChecked){stage.append(el('h3',tr('รายการข้าว: ','Rice meals: ')+missionCount));status.textContent=missionCount===1?tr('สำเร็จ ✓ ได้หนึ่งจาน ระบบรับคำสั่ง ไม่ได้หมายความว่าอาหารพร้อมแล้ว','Done ✓ One meal. The order is received; the food is not ready yet.'):missionCount===0?tr('ยังไม่มีรายการ ลองทำให้ได้ข้าว 1 จาน','No order yet. Try to get one rice meal.'):tr('มีรายการซ้ำ ลองยกเลิกรายการจำลองแล้วทำใหม่ อะไรทำให้ไม่แน่ใจ?','Duplicate orders. Cancel the practice order and try again. What made you uncertain?');}}stage.append(status);root.append(stage);if(missionHint)root.append(el('p',missionIndex===0?tr('คำใบ้: ① คือน้ำดื่ม ② คือน้ำผลไม้ ← ย้อนกลับ → ยืนยัน','Hint: ① is water. ② is juice. ← goes back. → confirms.'):tr('คำใบ้: แม้ไม่มีข้อความตอบกลับ ระบบยังรับคำสั่ง กดตรวจรายการได้เลย','Hint: even without a message, the system received the order. Select Check order.'),'case-transfer'));const label=el('label',tr('เล่าให้เพื่อนฟัง: ฉันกดอะไร แล้วเกิดอะไรขึ้น?','Tell a friend: what did I press and what happened?'));label.append(el('p',tr('ชี้จุดที่ช่วยหรือทำให้สับสน แล้วจดในใบงานกระดาษ ไม่ต้องพิมพ์บนเว็บ','Point to what helped or confused you. Record it on your paper worksheet, not on this website.')));root.append(label);renderReflection(root);root.append(el('small',tr('จดบนใบงาน: A/B ของตัวอย่างนี้ ไม่ใช่ต้นแบบของเรา ปุ่มครูเริ่มใหม่ใช้รีเซ็ตการทดลอง ไม่มีคำสั่งซื้อจริง','Record this sample’s A/B on the worksheet, separately from your own prototype. Teacher reset resets the trial. No real orders are placed.')));}


