function renderInquiry(){const r=$('#inquiryCard');if(!r)return;const en=lang==='en',tr=(a,b)=>en?b:a;r.replaceChildren();r.append(el('span',tr('สังเกต → ลอง → อธิบาย','Notice → Try → Explain'),'pill'),el('h1',tr('ทำไมบางหน้าจอใช้ได้ทันที แต่บางหน้าจอทำให้งง?','Why can we use some screens right away, while others confuse us?')),el('p',tr('คิดก่อนลอง อะไรน่าจะช่วยผู้ใช้ได้? เลือกแล้วบอกเหตุผลกับเพื่อน','Predict first. What might help the user? Choose and tell a friend why.')));const row=el('div','','row wrap');[tr('สีที่ฉันชอบ','My favourite colours'),tr('รู้ว่าจะกดอะไรและรู้ผล','Knowing what to press and what happened'),tr('ต้องให้คนอื่นลองก่อน','We need someone else to try')].forEach((t,i)=>{const b=choice(t,()=>{inquiryChoice=i;renderInquiry()});b.setAttribute('aria-pressed',inquiryChoice===i);row.append(b)});r.append(row);const reply=el('p',inquiryChoice<0?'':tr('นี่คือข้อคาดเดา ยังไม่ตัดสินว่าใครถูก ไปลองขนาดปุ่ม คำกำกับ และผลตอบกลับ แล้วกลับมาดูเหตุผลของเรา','This is a prediction, not a mark. Explore size, labels and feedback, then revisit your reason.'),'inquiry-response');reply.setAttribute('role','status');r.append(reply,el('p',tr('ครูมีเครื่องเดียว: ให้ตัวแทนลองกด คนอื่นสังเกตและชี้หลักฐาน ถามว่าผู้ใช้ต้องทำอะไรให้สำเร็จ','One teacher device: a representative clicks; everyone else observes and points to evidence. What must the user finish?')));}
const journeyQuizText={th:[['ผู้ใช้ยังอ่านไม่คล่องและอยากขอคำใบ้ จะลองแบบไหนก่อน?',['คำว่า ขอคำใบ้ อย่างเดียว','รูป ? พร้อมคำว่า ขอคำใบ้'],1,'รูปพร้อมคำอาจช่วยผู้ที่อ่านไม่คล่อง แต่ต้องให้เขาลองจริง ไม่ใช่ทุกคนเข้าใจรูปเหมือนกัน','คำอย่างเดียวอาจชัดสำหรับผู้อ่านคล่อง ลองให้ผู้ใช้คนนี้เทียบกับรูปพร้อมคำ'],['หน้าจอบอก “รับรายการข้าวแล้ว” เรารู้อะไร?',['ระบบรับรายการแล้ว','อาหารพร้อมกินแล้ว'],0,'ใช่ เรารู้ว่าระบบรับรายการ ไม่ได้แปลว่าอาหารทำเสร็จ','ข้อความยืนยันการรับรายการ ยังไม่ได้บอกว่าอาหารพร้อม'],['เพื่อนเลือกน้ำผลไม้ผิด ควรมีอะไร?',['เพิ่มปุ่มย้อนกลับเพื่อเปลี่ยน','ใช้ปุ่มเดียวเพื่อให้หน้าจอเรียบง่าย'],0,'กรณีเลือกผิด ทางย้อนกลับช่วยแก้ได้ แม้มีปุ่มเพิ่ม ต้องลองว่าผู้ใช้หาเจอไหม','ปุ่มน้อยทำให้หน้าจอเรียบง่ายได้ แต่กรณีนี้ผู้ใช้ต้องเปลี่ยนเครื่องดื่มที่เลือกผิด']],en:[['The user is still learning to read and wants a hint. Which would you test first?',['The words Get a hint only','A ? picture with Get a hint'],1,'Picture plus words may help this reader. Test it: people do not all interpret pictures alike.','Words alone may suit fluent readers. Ask this user to compare them with picture plus words.'],['The screen says “Rice order received”. What do we know?',['The system received the order','The food is ready to eat'],0,'Yes. We know the order arrived, not that the food is cooked.','Receiving an order does not mean the food is ready.'],['A friend chose juice by mistake. What would help?',['Add a Back button to change the choice','Use one button for a simpler screen'],0,'Here, Back allows recovery despite adding a button. Test whether the user can find it.','Fewer buttons can simplify a screen, but this user needs to change a mistaken drink choice.']]};
function renderJourneyQuiz(){const r=$('#journeyQuiz');if(!r)return;const focusIndex=r.contains(document.activeElement)?[...r.querySelectorAll('button')].indexOf(document.activeElement):-1;const en=lang==='en',q=journeyQuizText[lang][journeyQuestion],answer=journeyAnswers[journeyQuestion];r.replaceChildren();r.append(el('span',(journeyQuestion+1)+' / 3','pill'),el('h2',en?'Choose, explain, then try again':'เลือก อธิบาย แล้วลองใหม่'),el('h3',q[0]));const row=el('div','','row wrap');q[1].forEach((text,i)=>{const b=choice(text,()=>{journeyAnswers[journeyQuestion]=i;renderJourneyQuiz()});b.setAttribute('aria-pressed',answer===i);row.append(b)});r.append(row);const result=el('p',answer===null?(en?'Tell a friend why before choosing.':'บอกเหตุผลกับเพื่อนก่อนเลือก'):q[answer===q[2]?3:4],'quiz-feedback');result.setAttribute('role','status');r.append(result);const nav=el('div','','row wrap');nav.append(choice(en?'Previous question':'ข้อก่อนหน้า',()=>{journeyQuestion=Math.max(0,journeyQuestion-1);renderJourneyQuiz()}),choice(en?'Try this question again':'ลองข้อนี้ใหม่',()=>{journeyAnswers[journeyQuestion]=null;renderJourneyQuiz()}),choice(en?'Next question':'ข้อถัดไป',()=>{journeyQuestion=Math.min(2,journeyQuestion+1);renderJourneyQuiz()}));nav.children[0].disabled=journeyQuestion===0;nav.children[2].disabled=journeyQuestion===2;r.append(nav,el('small',en?'No speed score. Explain how the design helps the user finish the task.':'ไม่จับคะแนนความเร็ว อธิบายว่าการออกแบบช่วยให้ผู้ใช้ทำงานสำเร็จอย่างไร'));if(focusIndex>=0){const target=r.querySelectorAll('button')[focusIndex];if(target&&!target.disabled)target.focus();else{const heading=r.querySelector('h3');heading.tabIndex=-1;heading.focus()}}}
function renderFun(){const r=$('#funCard');if(!r)return;const en=lang==='en',tr=(a,b)=>en?b:a;r.replaceChildren();if(document.body.dataset.slide==='external'){r.append(el('h2',tr('ลองดูปุ่มปรับเสียงที่ชวนงง','Explore a confusing volume control')),el('p',tr('กิจกรรมเสริม ครูฉาย Pump it volume เป็นแบบจำลองระดับเสียง ไม่ใช่การปรับเสียงเครื่องจริง เด็กลองกดเมื่อครูกำกับเท่านั้น','Optional: the teacher projects Pump it volume, a simulated volume control, not the device’s sound setting. Children interact only with teacher guidance.')));const list=el('ul','');[tr('หน้าเดียวกันมีช่องวันเกิด อีเมล เบอร์โทร และลิงก์อื่น ห้ามกรอกข้อมูลหรือเปิดลิงก์อื่น','The same page contains birthday, email and phone fields and other links. Do not fill them in or open other links.'),tr('ครูตรวจหน้าเว็บก่อนคาบทุกครั้ง เว็บภายนอกเปลี่ยนได้ ถ้าไม่เหมาะให้ใช้ตู้ชวนงงในสื่อนี้','Teacher: check the page before each lesson. External sites can change. Use our confusing dispenser if unsuitable.'),tr('ถาม: อยากปรับเสียงต้องทำอะไร? ตรงไหนทำให้เหนื่อยหรือไม่แน่ใจ? จะปรับปุ่มอย่างไร?','Ask: what do you have to do to change the volume? What feels tiring or unclear? How would you redesign it?')].forEach(x=>list.append(el('li',x)));r.append(list);const link=el('a',tr('ครูเปิดตัวอย่าง Pump it volume ↗','Teacher: open Pump it volume ↗'),'primary external-button');link.href='https://mattw.io/bad-ui/#pump-it-volume';link.target='_blank';link.rel='noopener noreferrer';r.append(link,choice(tr('กลับไปตู้ชวนงงในสื่อนี้','Use our in-site dispenser'),()=>goSlide(deckSlides.findIndex(x=>x[0]==='fun'))));return}r.append(el('h2',tr('ตู้ชวนงง: ปุ่มไหนได้น้ำ?','Confusing dispenser: which button gives water?')),el('p',tr('ตัวอย่างตั้งใจออกแบบให้ชวนงงเพื่อเรียนรู้ ไม่ใช่คำแนะนำให้ทำตาม ลองเลือกน้ำดื่ม','Intentionally confusing for learning, not a design to copy. Try to choose water.')));const row=el('div','','row wrap');[tr('กดนี่มั้ง?','Maybe here?'),tr('อันนี้หรือเปล่า?','Or this one?'),tr('รู้ไหมว่าอันไหน?','Can you guess?')].forEach((t,i)=>row.append(choice(t,()=>{funAnswer=i;renderFun()})));r.append(row);const message=el('p',funAnswer<0?'':funAnswer===1?tr('ได้น้ำดื่มแล้ว! แต่ครั้งแรกต้องเดาไหม?','Water selected! But did you have to guess the first time?'):tr('ได้ลมหนึ่งแก้ว! ลองอีกปุ่มได้ ปุ่มกลางคือน้ำดื่ม','A cup of air! Try again. The middle button gives water.'),'quiz-feedback');message.setAttribute('role','status');r.append(message,choice(tr('เริ่มใหม่','Restart'),()=>{funAnswer=-1;renderFun()}),el('p',tr('ชี้จุดที่ทำให้งง เสนอคำใหม่บนกระดาษ แล้วให้เพื่อนลอง ไม่หัวเราะคนที่กดผิด','Point to what is confusing. Suggest new labels on paper and let a friend try. Do not laugh at someone who chooses incorrectly.')));}

let selectedMission=0;
function stepSlide(delta){let next=slideIndex+delta;const id=deckSlides[slideIndex][0];if(delta>0&&id==='route')next=deckSlides.findIndex(x=>x[0]===(selectedMission?'rice':'water'));if(delta<0&&((selectedMission===1&&id==='rice')||(selectedMission===0&&id==='water')))next=deckSlides.findIndex(x=>x[0]==='route');if(delta>0&&id==='water-note')next=deckSlides.findIndex(x=>x[0]==='plan');if(delta<0&&id==='plan')next=deckSlides.findIndex(x=>x[0]===(selectedMission?'rice-note':'water-note'));goSlide(next)}
function renderRoute(){const r=$('#routeCard');if(!r)return;const en=lang==='en',tr=(a,b)=>en?b:a,id=document.body.dataset.slide;r.replaceChildren();if(id==='route'){r.append(el('h2',tr('เลือกหนึ่งภารกิจให้ทีมตรวจ','Choose one mission to inspect')),el('p',tr('ครูให้ตัวแทนกด A/B คนอื่นสังเกตและจดบนใบงาน ปุ่มถัดไปจะไปเฉพาะภารกิจที่เลือก','A representative tries A/B on the teacher device. Others observe and record on paper. Next follows only your chosen mission.')));const row=el('div','','row wrap');[tr('💧 น้ำดื่มให้น้อง','💧 Water for a younger child'),tr('🍚 ข้าวหนึ่งจาน','🍚 One rice meal')].forEach((t,i)=>{const b=choice(t,()=>{selectedMission=i;renderRoute()});b.setAttribute('aria-pressed',selectedMission===i);row.append(b)});r.append(row,el('p',tr('บัตรภาพพร้อมใช้: 💧 เลือกน้ำดื่ม ไม่ใช่น้ำผลไม้ | 🍚 ให้ระบบรับข้าว 1 จาน','Picture tasks: 💧 select water, not juice | 🍚 get one rice meal into the order')));return}const retest=id==='retest';r.append(el('h2',retest?tr('ทดลองเปลี่ยนหนึ่งจุด','Try changing one feature'):tr('ตัดสินจากสิ่งที่ลอง ไม่ใช่แค่ความชอบ','Decide from evidence, not just preference')));const lines=retest?[tr('เลือกเปลี่ยนคำ ปุ่ม หรือผลตอบกลับเพียงเรื่องเดียวบนต้นแบบกระดาษ','Change just a label, a button or a response on your paper prototype.'),tr('ใช้ภารกิจเดิม ให้เพื่อนลองโดยไม่ชี้นำ ผู้สร้างเปลี่ยนแผ่นตามการกด','Use the same task. A friend tries without hints; the maker changes sheets for the action.'),tr('จดสิ่งที่เกิดก่อนและหลัง ถ้าเพื่อนคล่องขึ้น อาจจำวิธีได้แล้ว','Record before and after. Improved performance may also come from practice.')]:[tr('คงแบบเดิมได้ ถ้าเปรียบเทียบทางเลือกแล้วมีหลักฐานว่าเหมาะกว่า','You may keep the original if comparing an alternative gives evidence that it fits better.'),tr('หรือใช้แบบใหม่ โดยบอกว่าช่วยผู้ใช้ทำอะไรได้ดีขึ้น','Or use the alternative and explain what it helps the user do.'),tr('ยังไม่แน่ใจก็บอกได้ ระบุว่าจะให้ใครลองอะไรต่อ ก่อนนำเสนอ','If uncertain, say so. State who should try what next before presenting.')];lines.forEach(x=>r.append(el('p',x)));}
